"""Search sector CRUD + CoT fan-out for civil SAR (ПСР)."""

from __future__ import annotations

import json
import uuid
from datetime import datetime, timezone

from flask import Blueprint, jsonify, request
from flask_babel import gettext
from flask_security import auth_required, current_user

from opentakserver.blueprints.ots_api.api import route_cot
from opentakserver.extensions import db, logger, socketio
from opentakserver.models.Mission import Mission
from opentakserver.models.SearchSector import SearchSector

search_sector_api = Blueprint("search_sector_api", __name__)

_table_ready = False


def ensure_search_sectors_table():
    global _table_ready
    if _table_ready:
        return
    try:
        SearchSector.__table__.create(bind=db.engine, checkfirst=True)
        _table_ready = True
    except Exception as e:
        logger.warning("search_sectors table ensure failed: %s", e)


def _validate_mission_name(name):
    if not name:
        return None
    exists = db.session.execute(db.session.query(Mission).filter_by(name=name)).first()
    if not exists:
        return None
    return name


def build_sector_cot_xml(sector: SearchSector) -> str:
    import html as html_mod

    coords = json.loads(sector.coordinates or "[]")
    if len(coords) < 3:
        raise ValueError("sector needs ≥3 vertices")
    ring = list(coords)
    if ring[0] != ring[-1]:
        ring = ring + [ring[0]]
    link_points = " ".join(f"{lat:.6f},{lon:.6f},0.0" for lat, lon in ring)
    lat0, lon0 = coords[0][0], coords[0][1]
    now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    from datetime import timedelta

    stale = (datetime.now(timezone.utc) + timedelta(days=14)).strftime("%Y-%m-%dT%H:%M:%SZ")
    name = html_mod.escape(sector.name or "Sector", quote=True)
    assigned = html_mod.escape(sector.assigned_to or "", quote=True)
    remarks = f"psr:sector assigned:{assigned}".strip()
    color = -2130706432
    uid = html_mod.escape(sector.cot_uid or sector.uid, quote=True)
    return f"""<?xml version='1.0' encoding='UTF-8' standalone='yes'?>
<event version='2.0' uid='{uid}' type='u-d-f' time='{now}' start='{now}' stale='{stale}' how='h-e'>
  <point lat='{lat0:.6f}' lon='{lon0:.6f}' hae='0.0' ce='9999999.0' le='9999999.0'/>
  <detail>
    <contact callsign='{name}'/>
    <link point='{link_points}'/>
    <strokeColor value='{color}'/>
    <strokeWeight value='3'/>
    <fillColor value='{color}'/>
    <labels_on value='true'/>
    <remarks>{remarks}</remarks>
  </detail>
</event>"""


def _emit_sector(sector: SearchSector):
    socketio.emit("search_sector", sector.to_json(), namespace="/socket.io")


@search_sector_api.route("/api/search_sectors", methods=["GET"])
@auth_required()
def list_sectors():
    ensure_search_sectors_table()
    rows = db.session.execute(db.session.query(SearchSector)).scalars().all()
    return jsonify({"results": [r.to_json() for r in rows], "success": True})


@search_sector_api.route("/api/search_sectors", methods=["POST"])
@auth_required()
def create_sector():
    ensure_search_sectors_table()
    body = request.get_json(silent=True) or {}
    coords = body.get("coordinates") or []
    if not isinstance(coords, list) or len(coords) < 3:
        return jsonify({"success": False, "error": gettext("Need at least 3 coordinates")}), 400

    uid = body.get("uid") or str(uuid.uuid4())
    mission_name = _validate_mission_name(body.get("mission_name"))
    if body.get("mission_name") and not mission_name:
        return jsonify({"success": False, "error": gettext("Unknown mission")}), 400
    now = datetime.now(timezone.utc)
    sector = SearchSector(
        uid=uid,
        name=(body.get("name") or "Сектор")[:255],
        assigned_to=(body.get("assigned_to") or None),
        mission_name=mission_name,
        status=(body.get("status") or "active")[:32],
        coordinates=json.dumps(coords),
        cot_uid=uid,
        created=now,
        updated=now,
    )
    db.session.add(sector)
    db.session.commit()

    try:
        xml = build_sector_cot_xml(sector)
        route_cot(xml, current_user)
    except Exception as e:
        logger.error("Failed to route sector CoT: %s", e)

    _emit_sector(sector)
    return jsonify({"success": True, "sector": sector.to_json()})


@search_sector_api.route("/api/search_sectors/<uid>", methods=["PATCH"])
@auth_required()
def patch_sector(uid):
    ensure_search_sectors_table()
    sector = db.session.execute(db.session.query(SearchSector).filter_by(uid=uid)).scalar_one_or_none()
    if not sector:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    if "name" in body:
        sector.name = (body["name"] or sector.name)[:255]
    if "assigned_to" in body:
        sector.assigned_to = body["assigned_to"]
    if "mission_name" in body:
        raw = body["mission_name"]
        if raw:
            validated = _validate_mission_name(raw)
            if not validated:
                return jsonify({"success": False, "error": gettext("Unknown mission")}), 400
            sector.mission_name = validated
        else:
            sector.mission_name = None
    if "status" in body:
        sector.status = (body["status"] or sector.status)[:32]
    if "coordinates" in body and isinstance(body["coordinates"], list) and len(body["coordinates"]) >= 3:
        sector.coordinates = json.dumps(body["coordinates"])
    sector.updated = datetime.now(timezone.utc)
    db.session.commit()

    try:
        xml = build_sector_cot_xml(sector)
        route_cot(xml, current_user)
    except Exception as e:
        logger.error("Failed to route sector CoT: %s", e)

    _emit_sector(sector)
    return jsonify({"success": True, "sector": sector.to_json()})


@search_sector_api.route("/api/search_sectors/<uid>", methods=["DELETE"])
@auth_required()
def delete_sector(uid):
    ensure_search_sectors_table()
    sector = db.session.execute(db.session.query(SearchSector).filter_by(uid=uid)).scalar_one_or_none()
    if not sector:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    db.session.delete(sector)
    db.session.commit()
    socketio.emit("search_sector_delete", {"uid": uid}, namespace="/socket.io")
    return jsonify({"success": True})


def upsert_sector_from_cot(uid: str, name: str, coordinates, assigned_to: str | None = None):
    """Called from cot_parser when inbound u-d-f carries psr:sector."""
    ensure_search_sectors_table()
    if not coordinates or len(coordinates) < 3:
        return
    now = datetime.now(timezone.utc)
    sector = db.session.execute(db.session.query(SearchSector).filter_by(uid=uid)).scalar_one_or_none()
    if sector is None:
        sector = SearchSector(
            uid=uid,
            name=name or "Sector",
            assigned_to=assigned_to,
            status="active",
            coordinates=json.dumps(coordinates),
            cot_uid=uid,
            created=now,
            updated=now,
        )
        db.session.add(sector)
    else:
        sector.name = name or sector.name
        if assigned_to is not None:
            sector.assigned_to = assigned_to
        sector.coordinates = json.dumps(coordinates)
        sector.updated = now
    db.session.commit()
    _emit_sector(sector)
